// sheetId: Your Google Sheet ID (from the URL between /d/ and /edit)
const sheetId = 'YOUR-GOOGLE-SHEET-ID';

return [{ json: { sheetId } }];

const today = new Date().toISOString().split('T')[0];
const result = [];
const allItems = $input.all();
for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i];
  const raw = item.json.send_date;
  if (raw) {
    try {
      const normalized = new Date(raw).toISOString().split('T')[0];
      if (normalized === today) {
        result.push({ json: item.json });
      }
    } catch (e) {}
  }
}
return result;

const items = $input.all();
const today = new Date();
const days = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const months = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const weekday = days[today.getDay()];
const dateStr = today.getDate() + ' ' + months[today.getMonth()] + ' ' + today.getFullYear();
const products = items.map(i => i.json);
const count = products.length;
const cards = [];
for (let i = 0; i < products.length; i++) {
  const p = products[i];
  const hasRef = p.referral_link && p.referral_link.trim() !== '';
  let card = '<div style="margin-bottom:24px;border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">';
  if (p.image_url) { card += '<div style="padding:12px 12px 0;"><img src="' + p.image_url + '" style="width:100%;max-height:220px;object-fit:contain;display:block;" alt="' + p.product_name + '" /></div>'; }
  card += '<div style="padding:10px 14px 12px;">';
  card += '<h2 style="margin:0 0 4px;font-size:15px;color:#111;">' + p.product_name + '</h2>';
  card += '<p style="margin:0 0 10px;color:#666;line-height:1.4;font-size:13px;">' + p.description + '</p>';
  if (hasRef) {
    card += '<a href="' + p.referral_link + '" style="display:inline-block;background:#000;color:#fff;padding:7px 16px;border-radius:6px;text-decoration:none;font-size:13px;">Learn more →</a>';
  }
  card += '</div></div>';
  cards.push(card);
}
const productCards = cards.join('');
const h1text = count + ' new product' + (count > 1 ? 's' : '') + ' for you today';
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:0;background:#f9fafb;"><div style="max-width:600px;margin:0 auto;padding:24px;font-family:-apple-system,sans-serif;"><h1 style="margin:0 0 24px;font-size:24px;color:#111;">' + h1text + '</h1>' + productCards + '<p style="margin-top:32px;font-size:12px;color:#999;">You are receiving this because you subscribed to our product newsletter.</p></div></body></html>';
const subject = count + ' new product' + (count > 1 ? 's' : '') + ' for you – ' + weekday + ', ' + dateStr;
return [{ json: { html, subject } }];

const template = $('Build HTML Email').first().json;
const recipients = $input.all();
const result = [];
for (let i = 0; i < recipients.length; i++) {
  const email = recipients[i].json.email;
  if (!email) continue;
  result.push({ json: { to: email, subject: template.subject, html: template.html } });
}
return result;
